/**
 * Difficulty profiles: plain data that says how each option value shifts a game's difficulty.
 * Scale: 0 (trivial) to 10 (brutal). The number is an estimate, never a measurement.
 */

export const PROFILE_FORMAT = 1;

/** drafted: written by Claude from the option metadata; reviewed: checked by someone who plays the game; estimated: generated by rules. */
export type ProfileStatus = 'drafted' | 'reviewed' | 'estimated';

/** How one option moves the score. Shifts are relative to the option's default: the default always adds 0. */
export interface OptionEffect {
  /** One sentence for the "why this number" list. */
  why?: string;
  /** Shift per value as written in YAML ("true"/"false" for switches, the choice key for choices). A value that is not listed shifts by 0. */
  values?: Record<string, number>;
  /** range and named_range: shift by number, as points [value, shift] with rising values; in between the shift is a straight line, outside it holds the end point. */
  curve?: [number, number][];
}

export interface DifficultyProfile {
  format: typeof PROFILE_FORMAT;
  /** Game name exactly as in schema.json. */
  game: string;
  /** The Archipelago version the profile was written against. */
  apVersion: string;
  status: ProfileStatus;
  /** Score with every option at its default, 0 to 10. */
  base: number;
  options: Record<string, OptionEffect>;
}

/** One option's pull on the score, for the "why" list. */
export interface Contribution {
  key: string;
  displayName: string;
  /** The value as shown to a person ("On", "hard", "30"). */
  valueText: string;
  /** Change in score, relative to the game's defaults. Never 0. */
  delta: number;
  why: string | null;
}

export interface ScoreResult {
  /** 0 to 10, unrounded. */
  score: number;
  /** Largest pull first. */
  contributions: Contribution[];
  /** Display names of options that are random or weighted (counted as an average) or whose value could not be read (counted at the default). */
  approximated: string[];
}

export type RatingSource = 'rated' | 'estimated' | 'none';

/** What the meter shows. */
export interface Rating {
  source: RatingSource;
  /** null when source is none. */
  status: ProfileStatus | null;
  /** 0 to 10, or null when not rated. */
  score: number | null;
  label: string | null;
  contributions: Contribution[];
  approximated: string[];
  /** Plain-words note about where the number comes from (or why there is none). */
  note: string;
}
